PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE products (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  sku        TEXT    NOT NULL UNIQUE,
  name       TEXT    NOT NULL,
  region     TEXT    NOT NULL,
  regionLabel TEXT   NOT NULL,
  category   TEXT    NOT NULL,
  price      INTEGER NOT NULL,
  mrp        INTEGER NOT NULL,
  city       TEXT    NOT NULL,
  badge      TEXT    NOT NULL DEFAULT '',
  image      TEXT    NOT NULL DEFAULT '',
  altImage   TEXT    NOT NULL DEFAULT '',
  inStock    INTEGER NOT NULL DEFAULT 1,
  created_at TEXT    NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT    NOT NULL DEFAULT (datetime('now'))
, stock_count INTEGER DEFAULT 0, weightGrams INTEGER DEFAULT NULL, variants TEXT, low_stock_threshold INTEGER DEFAULT 3, packing_weight_grams INTEGER DEFAULT NULL);
CREATE TABLE orders (
  id        TEXT PRIMARY KEY,  -- e.g. "CC-20260627-A7X3"
  user_id   INTEGER,
  email     TEXT,
  phone     TEXT,
  name      TEXT,
  items     TEXT NOT NULL,     -- JSON array
  total     INTEGER NOT NULL,  -- in paise
  subtotal  INTEGER NOT NULL,
  discount  INTEGER DEFAULT 0,
  address   TEXT NOT NULL,     -- JSON
  razorpay_payment_id TEXT,
  status    TEXT NOT NULL DEFAULT 'confirmed',  -- confirmed|processing|shipped|delivered|cancelled
  awb       TEXT DEFAULT '',
  awb_url   TEXT DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, payment_method TEXT DEFAULT 'razorpay', razorpay_order_id TEXT, shipprime_awb TEXT, shipprime_order_id TEXT, test_mode INTEGER DEFAULT 0, shipprime_error TEXT, shipprime_attempts INTEGER NOT NULL DEFAULT 0, shipprime_last_attempt_at TEXT, track_token TEXT);
CREATE TABLE sessions (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id    INTEGER NOT NULL,
  token      TEXT UNIQUE NOT NULL,
  email      TEXT,
  name       TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE users (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  email      TEXT,
  phone      TEXT,
  name       TEXT NOT NULL,
  password   TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, is_guest INTEGER DEFAULT 0);
CREATE TABLE wishlist (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, product_sku TEXT NOT NULL, created_at TEXT DEFAULT (datetime('now')), UNIQUE(user_id, product_sku));
CREATE TABLE reviews (id INTEGER PRIMARY KEY AUTOINCREMENT, product_sku TEXT NOT NULL, user_id INTEGER, name TEXT NOT NULL, rating INTEGER NOT NULL CHECK(rating>=1 AND rating<=5), review_text TEXT NOT NULL, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE password_resets (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL,
  token TEXT NOT NULL UNIQUE,
  type TEXT NOT NULL DEFAULT 'reset',      -- 'reset' | 'magiclink' | 'cod_verify'
  expires_at TEXT NOT NULL,
  used INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE order_events (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  order_id   TEXT NOT NULL,
  kind       TEXT NOT NULL,          -- 'shiprocket_push' | 'shiprocket_retry' | 'email' | 'note'
  ok         INTEGER NOT NULL,       -- 1 success, 0 failure
  detail     TEXT,                    -- error message OR success JSON
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE settings (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL,
      updated_at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE admin_login_attempts (
  ip TEXT PRIMARY KEY,
  attempts INTEGER NOT NULL DEFAULT 0,
  locked_until TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE admin_users (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  username      TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  role          TEXT NOT NULL DEFAULT 'staff', -- 'owner' | 'staff'
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now'))
, role_expires_at TEXT DEFAULT NULL);
CREATE TABLE admin_sessions (
  token      TEXT PRIMARY KEY,
  user_id    INTEGER NOT NULL,
  role       TEXT NOT NULL,
  username   TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at TEXT NOT NULL
);
CREATE TABLE order_otps (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL,
  phone TEXT NOT NULL,
  otp TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  used INTEGER NOT NULL DEFAULT 0,
  attempts INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE cod_verifications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  token TEXT NOT NULL UNIQUE,
  email TEXT NOT NULL,
  phone TEXT NOT NULL,
  used INTEGER NOT NULL DEFAULT 0,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE rate_limits (
  bucket_key   TEXT PRIMARY KEY,
  count        INTEGER NOT NULL DEFAULT 0,
  window_start TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE login_otps (id INTEGER PRIMARY KEY AUTOINCREMENT, phone TEXT NOT NULL, otp TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, used INTEGER NOT NULL DEFAULT 0, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
DELETE FROM sqlite_sequence;
CREATE INDEX idx_products_region ON products(region);
CREATE INDEX idx_products_category ON products(category);
CREATE INDEX idx_products_instock ON products(inStock);
CREATE INDEX idx_products_sku ON products(sku);
CREATE INDEX idx_orders_email ON orders(email);
CREATE INDEX idx_orders_phone ON orders(phone);
CREATE INDEX idx_orders_user_id ON orders(user_id);
CREATE INDEX idx_orders_status ON orders(status);
CREATE INDEX idx_sessions_token ON sessions(token);
CREATE INDEX idx_sessions_user_id ON sessions(user_id);
CREATE UNIQUE INDEX idx_users_email ON users(email);
CREATE UNIQUE INDEX idx_users_phone ON users(phone);
CREATE INDEX idx_wishlist_user ON wishlist(user_id);
CREATE INDEX idx_reviews_sku ON reviews(product_sku);
CREATE INDEX idx_orders_payment_id ON orders(razorpay_payment_id);
CREATE INDEX idx_resets_token ON password_resets(token);
CREATE INDEX idx_resets_email ON password_resets(email);
CREATE INDEX idx_events_order ON order_events(order_id);
CREATE INDEX idx_events_kind ON order_events(kind);
CREATE INDEX idx_otps_email_phone ON order_otps(email, phone);
CREATE INDEX idx_login_otps_phone ON login_otps(phone);
